    const cart = new Cart();
    cart.add(productA, 2); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const result = await cart.checkout({ priceFetcher });

    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0].product.unitPriceCents).toBe(1200);
    expect(result.totals.subtotalCents).toBe(2400);
  });

  it("skips price refresh when priceFetcher not provided", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
  });

  it("throws InventoryError when item not available", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
  });

  it("uses sync tax calculator when asyncTaxProvider not provided", async () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);

    const result = await cart.checkout();
    expect(tax.computeTaxCents).toHaveBeenCalled();
    expect(result.totals.taxCents).toBe(50);
  });

  it("combines price refresh, inventory check, discount, async tax, and shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200, // $2 off
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 500, // $5 flat
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "FR",
    });
    cart.add(productA, 2); // original 1000 each

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500), // new price
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20), // 20% VAT
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal: 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    // discount: 200
    expect(result.totals.discountCents).toBe(200);
    // tax: 20% of (3000 - 200) = 20% of 2800 = 560
    expect(result.totals.taxCents).toBe(560);
    // shipping: 500
    expect(result.totals.shippingCents).toBe(500);
    // total: 2800 + 560 + 500 = 3860
    expect(result.totals.totalCents).toBe(3860);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service error",
    );
  });

  it("checks inventory for each line in order", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 3);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 1);
    expect(inventoryChecker.check).toHaveBeenCalledWith("b", 3);
  });

  it("first inventory denial wins when multiple lines fail", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "A gone" })
        .mockResolvedValueOnce({ available: false, reason: "B gone" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).productId).toBe("a");
      expect((e as InventoryError).message).toBe("A gone");
    }
  });

  it("returns result lines as snapshot (not internal state)", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    // Cart should still have the item
    expect(cart.itemCount).toBe(2);
    expect(result.lines).toHaveLength(1);
  });
});
