import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (id: string, weightGrams?: number, qty = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat rate for non-empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([line("a")], 4999)).toBe(799);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([line("a")], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([line("a")], 6000)).toBe(0);
    });

    it("returns flat rate when no threshold is set", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([line("a")], 99999)).toBe(799);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 2000, costCents: 700 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([line("a", undefined, 3)], 1000)).toBe(0);
    });

    it("selects the first bracket that fits", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 250g → ≤500g bracket → 300
      expect(calc.computeShippingCents([line("a", 250)], 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // exactly 500g → ≤500g bracket → 300
      expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(300);
      // 501g → ≤2000g bracket → 700
      expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(700);
    });

    it("uses highest bracket cost when weight exceeds all brackets (no overflow)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g → exceeds 5000g → default to highest bracket cost 1200
      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(1200);
    });

    it("uses overflowCostCents when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(2000);
    });

    it("sums weights across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300g * 2 + 200g * 1 = 800g → ≤2000g bracket → 700
      const lines = [line("a", 300, 2), line("b", 200, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted: WeightBracket[] = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(calc.computeShippingCents([line("a", 250)], 1000)).toBe(300);
    });
  });
});

