+
+    it("sums weights across multiple lines", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 300g * 2 + 200g * 1 = 800g → ≤2000g bracket → 700
+      const lines = [line("a", 300, 2), line("b", 200, 1)];
+      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
+    });
+
+    it("sorts brackets regardless of input order", () => {
+      const unsorted: WeightBracket[] = [
+        { upToGrams: 5000, costCents: 1200 },
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 2000, costCents: 700 },
+      ];
+      const calc = new WeightBasedShippingCalculator(unsorted);
+      expect(calc.computeShippingCents([line("a", 250)], 1000)).toBe(300);
+    });
+  });
+});
