import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Alpha", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Beta", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart – line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("add creates a new line", () => {
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for the same product", () => {
    cart.add(productA, 1);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(4);
  });

  it("add throws for non-positive quantity", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("add throws for non-integer quantity", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const badProduct: Product = { id: "x", name: "X", unitPriceCents: -10 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
      "Product nonexistent is not in the cart",
    );
  });

  it("updateQuantity throws for negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(productA, 1);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0].product.id).toBe("a");
    expect(snap[0].quantity).toBe(2);
    // mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart – totals (pricing pipeline)", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("subtotal sums price × quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 1000 * 2 = 2000
    cart.add(productB, 1); // 2000 * 1 = 2000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("applies discount, tax on discounted subtotal, and shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(175),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(productA, 5); // subtotal = 5000

    const t = cart.totals();
    expect(t.subtotalCents).toBe(5000);
    expect(t.discountCents).toBe(500);
    // tax is called with discounted subtotal
    expect(tax.computeTaxCents).toHaveBeenCalledWith(4500, "US-CA");
    expect(t.taxCents).toBe(175);
    // shipping is called with lines and discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      4500,
    );
    expect(t.shippingCents).toBe(300);
    expect(t.totalCents).toBe(4500 + 175 + 300);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal = 1000
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to US region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart – async checkout()", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 2); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const result = await cart.checkout({ priceFetcher });

    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0].product.unitPriceCents).toBe(1200);
    expect(result.totals.subtotalCents).toBe(2400);
  });

  it("skips price refresh when priceFetcher not provided", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
  });

  it("throws InventoryError when item not available", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
  });

  it("uses sync tax calculator when asyncTaxProvider not provided", async () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);

    const result = await cart.checkout();
    expect(tax.computeTaxCents).toHaveBeenCalled();
    expect(result.totals.taxCents).toBe(50);
  });

  it("combines price refresh, inventory check, discount, async tax, and shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200, // $2 off
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 500, // $5 flat
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "FR",
    });
    cart.add(productA, 2); // original 1000 each

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500), // new price
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20), // 20% VAT
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal: 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    // discount: 200
    expect(result.totals.discountCents).toBe(200);
    // tax: 20% of (3000 - 200) = 20% of 2800 = 560
    expect(result.totals.taxCents).toBe(560);
    // shipping: 500
    expect(result.totals.shippingCents).toBe(500);
    // total: 2800 + 560 + 500 = 3860
    expect(result.totals.totalCents).toBe(3860);
  });

